<a class="btn btn-outline-secondary mb-3" href="<?= BASE_URL ?>/academy/manage">Volver a mis cursos de gestión</a><h1 class="h3 mb-4"><?= e($title) ?></h1>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= e($success) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?><?php if ($errors): ?><div class="alert alert-danger" role="alert"><ul class="mb-0"><?php foreach ($errors as $message): ?><li><?= e($message) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="card card-body mb-4" method="post" action="<?= BASE_URL ?>/academy/course/save<?= isset($course['id']) ? '?id='.(int)$course['id'] : '' ?>"><?= Csrf::field() ?><div class="row g-3"><div class="col-12"><label class="form-label" for="titulo">Título *</label><input class="form-control" id="titulo" name="titulo" required maxlength="160" value="<?= e($course['titulo'] ?? '') ?>"></div><div class="col-12"><label class="form-label" for="descripcion">Descripción</label><textarea class="form-control" id="descripcion" name="descripcion" rows="4" maxlength="15000"><?= e($course['descripcion'] ?? '') ?></textarea></div><div class="col-12"><label class="form-label" for="instructor_id">Instructor responsable *</label><select class="form-select" id="instructor_id" name="instructor_id" required <?= $user['rol']==='instructor' ? 'disabled' : '' ?>><?php foreach ($instructors as $option): ?><option value="<?= (int)$option['id'] ?>" <?= (int)($course['instructor_id'] ?? 0)===(int)$option['id'] ? 'selected' : '' ?>><?= e($option['nombre']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><div class="form-check"><input class="form-check-input" type="checkbox" id="estado" name="estado" value="1" <?= !empty($course['estado']) ? 'checked' : '' ?>><label class="form-check-label" for="estado">Curso activo</label></div><p class="form-text">Desmarca para archivar. Se conserva el contenido y el progreso.</p></div><div class="col-md-6"><div class="form-check"><input class="form-check-input" type="checkbox" id="publicado" name="publicado" value="1" <?= !empty($course['publicado']) ? 'checked' : '' ?>><label class="form-check-label" for="publicado">Publicar en Academia</label></div><p class="form-text">Requiere al menos una lección activa. Los borradores no están disponibles para alumnos.</p></div><div class="col-12"><button class="btn btn-primary">Guardar curso</button></div></div></form>
<?php if (isset($course['id'])): ?><section class="card card-body"><div class="d-flex justify-content-between align-items-center gap-3 mb-3"><h2 class="h5 mb-0">Lecciones</h2><a class="btn btn-outline-primary" href="<?= BASE_URL ?>/academy/lesson/edit?course_id=<?= (int)$course['id'] ?>">Nueva lección</a></div><?php if (!$lessons): ?><p class="text-muted mb-0">Agrega la primera lección para poder publicar el curso.</p><?php endif; ?><?php foreach ($lessons as $lesson): ?><div class="d-flex justify-content-between gap-3 border-top py-3"><div><strong><?= (int)$lesson['orden'] ?> · <?= e($lesson['titulo']) ?></strong><div class="small text-muted"><?= $lesson['estado'] ? 'Activa' : 'Retirada' ?></div></div><a href="<?= BASE_URL ?>/academy/lesson/edit?course_id=<?= (int)$course['id'] ?>&id=<?= (int)$lesson['id'] ?>">Editar</a></div><?php endforeach; ?><a class="mt-3" href="<?= BASE_URL ?>/academy/course?id=<?= (int)$course['id'] ?>">Vista previa del curso</a></section><?php endif; ?>
<?php if (isset($course['id'])): ?>
<section class="card card-body mt-4"><h2 class="h5">Alumnos y progreso</h2><p class="small text-muted">Hasta 100 inscripciones, de más reciente a más antigua. Se consideran las lecciones activas actuales.</p>
<?php if (!$students): ?><p class="text-muted mb-0">Aún no hay alumnos inscritos.</p><?php else: $activeCount=count(array_filter($lessons,fn($item)=>(bool)$item['estado'])); ?>
<div class="table-responsive"><table class="table mb-0"><thead><tr><th>Alumno</th><th>Lecciones completadas</th><th>Estado</th></tr></thead><tbody><?php foreach ($students as $student): ?><tr><td><?= e($student['nombres'].' '.$student['apellidos']) ?><div class="small text-muted"><?= e($student['email']) ?></div></td><td><?= (int)$student['completadas'] ?> de <?= (int)$activeCount ?></td><td><?= $student['estado']==='completada' ? 'Lecciones completadas' : 'En curso' ?><?php if ($student['intento_id']): ?><div><a href="<?= BASE_URL ?>/academy/exam/result?id=<?= (int)$student['intento_id'] ?>">Último resultado</a></div><?php endif; ?><?php if ($student['certificado_codigo']): ?><div><a href="<?= BASE_URL ?>/academy/certificate?code=<?= e($student['certificado_codigo']) ?>">Certificado</a></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php endif; ?>
<?php if (isset($course['id'])): ?><section class="card card-body mt-4"><h2 class="h5">Examen final</h2><p>Crea preguntas, configura la nota mínima y activa la evaluación. Después del primer intento, el examen y las lecciones quedarán bloqueados.</p><a class="btn btn-outline-primary align-self-start" href="<?= BASE_URL ?>/academy/exam/manage?course_id=<?= (int)$course['id'] ?>">Gestionar examen final</a></section><?php endif; ?>

